// Reached via the emailed reset link's ?token=. The token itself is
// opaque to this page -- it's just forwarded verbatim to POST
// /auth/reset-password, which does the real verification (never
// decoded or trusted client-side here).
function renderResetPasswordPage(token, req) {
  const lang = resolveServerLang(req);
  const I18N_RESET = {
    fr: { title: 'Nouveau mot de passe', lblPassword: 'Nouveau mot de passe', pwHelp: '8 caractères minimum.', submit: 'Réinitialiser' },
    en: { title: 'New password', lblPassword: 'New password', pwHelp: '8 characters minimum.', submit: 'Reset' }
  };
  const bodyHtml = `${signupStyles()}${signupHeader()}
<main class="su-body">
  <div class="su-title"><h1 data-i18n="title">Nouveau mot de passe</h1></div>
  <div id="formErr" class="nl-error" style="display:none"></div>
  <div class="nl-field">
    <label class="nl-label" for="rp_password" data-i18n="lblPassword">Nouveau mot de passe</label>
    <input class="nl-input" id="rp_password" type="password" autocomplete="new-password" minlength="8" required>
    <p class="nl-help" data-i18n="pwHelp">8 caractères minimum.</p>
  </div>
</main>
<div class="su-bottom">
  <button type="button" class="nl-btn nl-btn--primary nl-btn--lg nl-btn--block" id="rp_submit" data-i18n="submit" onclick="submitReset()">Réinitialiser</button>
</div>
<script>
${nlAuthScript(I18N_RESET)}
function showError(msg) { var el = document.getElementById('formErr'); el.textContent = msg; el.style.display = 'block'; }
async function submitReset() {
  document.getElementById('formErr').style.display = 'none';
  var password = document.getElementById('rp_password').value;
  if (password.length < 8) { showError(window.__errorText('WEAK_PASSWORD')); return; }
  var btn = document.getElementById('rp_submit');
  btn.disabled = true;
  try {
    var res = await fetch('/auth/reset-password', {
      method: 'POST', credentials: 'same-origin',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ token: ${JSON.stringify(token || '')}, password: password })
    });
    var data = await res.json().catch(function() { return {}; });
    if (!res.ok || !data.ok) {
      showError(window.__errorText(data.errorKey, data.error));
      btn.disabled = false;
      return;
    }
    window.location.href = '/dashboard';
  } catch (e) {
    showError(window.__errorText('NETWORK_ERROR'));
    btn.disabled = false;
  }
}
</script>`;
  return nlDocument({ title: lang === 'en' ? 'New password' : 'Nouveau mot de passe', description: '', bodyHtml, lang });
}

// Scoped to exactly which dashboard state is rendering (state: 'none' |
// 'active' | 'deactivated', plus the active-only needsSeason/unverified
// flags) -- NOT a single static dict -- so a translation for a section
// that isn't actually shown (e.g. "Lance ta premiere saison" once a
// season already exists) never leaks into the shipped page, even
// inertly inside the JS dict. Same lesson as the public page's earlier
// bug this session already found and fixed (an unrelated string
// leaking into every response broke an existing test).
function buildDashI18n({ state, needsSeason, unverified, leagueName }) {
  const fr = { logout: 'Se déconnecter', navHome: 'Accueil', navRoster: 'Joueurs', navSchedule: 'Horaire', navSettings: 'Paramètres' };
  const en = { logout: 'Log out', navHome: 'Home', navRoster: 'Players', navSchedule: 'Schedule', navSettings: 'Settings' };
  if (state === 'none') {
    // Signup/recovery task, A1: this used to be a dead end -- an
    // interrupted signup (closed tab, dropped connection, browser
    // back) reaches an authenticated session with no league, and this
    // card had no action at all, only Log out. createLeagueCta links
    // straight to the real, working league-creation form
    // (/signup?step=2 -- confirmed rendering correctly for an
    // authenticated session; the dead end was purely this page never
    // offering the link, not that form being broken).
    Object.assign(fr, { dashTitle: 'Tableau de bord', noLeagueYet: "Tu n'as pas encore de ligue.", createLeagueCta: 'Créer ma ligue' });
    Object.assign(en, { dashTitle: 'Dashboard', noLeagueYet: "You don't have a league yet.", createLeagueCta: 'Create my league' });
  } else if (state === 'active') {
    Object.assign(fr, {
      noSeason: 'Pas de saison active',
      teamsLabel: 'équipes', playersLabel: 'joueurs',
      publicPage: 'Page publique', copyLink: 'Copier', copied: 'Copié !',
      publicPageDisabled: 'Désactivée -- personne ne peut voir cette page.',
      teams: 'Équipes', tracksResultsLabel: 'Résultats suivis :', tracksPlayerStatsLabel: 'Statistiques des joueurs suivies :', yes: 'Oui', no: 'Non',
      // B2 (stale-copy polish task): superseding the "Nouvelles
      // équipes chaque match" wording test/part49_teams_per_game_label.spec.js
      // previously locked with a do-not-revert comment (batch 2 Part 5,
      // then batch 5 Part 5) -- that history is kept here for context,
      // not as a rule still in force. This still reuses the exact
      // phrase the structure-picker itself uses for this same concept
      // (structureWeeklyTitle), just the picker's own wording changed
      // ("Équipes qui changent" -> "Sans équipes fixes"), so this tile
      // follows it, per this task's own explicit instruction to apply
      // the new wording everywhere these options appear.
      teamsPerGame: 'Sans équipes fixes', noFixedTeams: 'Aucune équipe fixe',
      // C2 (empty-states polish task): clarifies what the dashboard
      // tile's bare number counts, for weekly_draw only.
      teamsPerGameCount: 'équipes disponibles',
      noFixedTeamsDesc: "Cette ligue n'a pas d'équipes fixes -- c'est une liste de joueurs unique, sans répartition en équipes.",
      weeklyDrawTeamsDesc: 'Ces équipes sont assignées à chaque match, pas de façon permanente aux joueurs.',
      // Live-testing task (batch 5), Part 6: the dashboard's own
      // ongoing "what's still worth doing" checklist -- computed from
      // real state (no players yet, team names still the generic
      // default, roster limits never set), not a one-time flag, so it
      // naturally disappears once each is genuinely addressed.
      nextStepsTitle: 'Prochaines étapes', nsCreateSchedule: "Créer l'horaire", nsAddPlayers: 'Ajouter des joueurs', nsNameTeams: 'Nommer tes équipes', nsRosterLimits: "Définir l'effectif"
      // Live-testing task (batch 5), Part 7: coAdmins/invite*/
      // deactivate*/hardDelete* used to live here too -- moved to
      // I18N_SETTINGS alongside the sections that use them (see
      // handleLeagueSettingsPage). The 'deactivated' state's own dict
      // branch below still has its own hardDelete* keys -- that
      // section is the one genuine exception that stays on the
      // dashboard (see this function's own comment for why).
    });
    Object.assign(en, {
      noSeason: 'No active season',
      teamsLabel: 'teams', playersLabel: 'players',
      publicPage: 'Public page', copyLink: 'Copy', copied: 'Copied!',
      publicPageDisabled: "Disabled -- no one can see this page.",
      teams: 'Teams', tracksResultsLabel: 'Results tracked:', tracksPlayerStatsLabel: 'Player stats tracked:', yes: 'Yes', no: 'No',
      teamsPerGame: 'Pickup with teams', noFixedTeams: 'No fixed teams',
      teamsPerGameCount: 'team names available',
      noFixedTeamsDesc: "This league has no fixed teams -- it's a single player list, with no team split.",
      weeklyDrawTeamsDesc: 'These teams are assigned per game, not permanently to players.',
      nextStepsTitle: 'Next steps', nsCreateSchedule: 'Create the schedule', nsAddPlayers: 'Add players', nsNameTeams: 'Name your teams', nsRosterLimits: 'Set roster size'
    });
    if (needsSeason) {
      Object.assign(fr, {
        nextStep: 'Prochaine étape', startSeason: 'Lance ta première saison',
        startSeasonDesc: 'Choisis un nom pour ta saison. Tu pourras créer des matchs ensuite.',
        seasonNameLabel: 'Nom de la saison', seasonNamePh: 'Ex. Saison Hiver 2026', seasonStartBtn: 'Créer la saison',
        checklistTitle: 'Pour bien partir',
        ckLeague: 'Créer la ligue', ckTeams: 'Nommer les équipes', ckPlayerCount: 'Choisir le nombre de joueurs', ckPlayers: 'Ajouter les joueurs', ckSeason: 'Créer la saison',
        ckReminders: 'Activer les rappels automatiques'
      });
      Object.assign(en, {
        nextStep: 'Next step', startSeason: 'Start your first season',
        startSeasonDesc: 'Choose a name for your season. You can create events after.',
        seasonNameLabel: 'Season name', seasonNamePh: 'E.g. Winter Season 2026', seasonStartBtn: 'Create the season',
        checklistTitle: 'Getting started',
        ckLeague: 'Create the league', ckTeams: 'Name the teams', ckPlayerCount: 'Choose your player count', ckPlayers: 'Add players', ckSeason: 'Create a season',
        ckReminders: 'Turn on reminders'
      });
    } else {
      // Live-testing task (batch 6), Part 7: the full season-management
      // form (name/structure/roster-limits override, submitSeasonMgmt)
      // used to live here, fully expanded on the dashboard home -- it's
      // now on Settings instead (handleLeagueSettingsPage's own
      // "seasonMgmtTitle" section, right before the league-default
      // structure section it sits next to thematically), reachable via
      // this small "Modifier" link next to the season badge below. Only
      // the read-only label + edit link stay here.
      // 4c (fixed-teams investigation follow-up batch, small fixes): a
      // space before the colon is French typography -- English takes
      // none. The colon now lives IN the label itself (with each
      // language's own correct spacing) rather than as punctuation
      // hardcoded once in the surrounding HTML, which could only ever
      // be right for one language regardless of which one a client-
      // side toggle actually switched to. Swept the rest of this
      // file's own hardcoded ` : ` template literals for the same
      // leak -- one more real instance found and fixed the same way,
      // the Settings page's own "Statistiques suivies : Oui/Non" label
      // (tracksStatsLabel, handleLeagueSettingsPage). Every other
      // " : "-shaped literal found is SMBHL's own dual-display pattern
      // (French primary text with a separate, already-correctly-
      // punctuated English <span class="en"> shown alongside it, not a
      // toggle-and-replace) or already a correctly per-language-
      // punctuated dict pair (sendPanelDesc) -- neither is this bug.
      Object.assign(fr, { currentSeasonLabel: 'Saison actuelle :', editSeason: 'Modifier', startNewSeasonLink: 'Démarrer une nouvelle saison' });
      Object.assign(en, { currentSeasonLabel: 'Current season:', editSeason: 'Edit', startNewSeasonLink: 'Start a new season' });
      // Live-testing task (batch 6), Part 8: "current-week status" card
      // (eventWeekStatus) -- only ever rendered once a season exists
      // (weekStatusHtml itself is '' under needsSeason), so scoped here
      // exactly like currentSeasonLabel/editSeason just above.
      // B3: weekStatusNoEvent/weekStatusCreateBtn removed -- this card
      // no longer has a "no event yet" state at all (see weekStatusHtml's
      // own comment); that prompt now lives in the unified next-steps
      // checklist as nsCreateSchedule instead.
      Object.assign(fr, {
        weekStatusTitle: 'Cette semaine', weekStatusDetailBtn: 'Voir le match',
        weekStatusConfirmed: 'confirmés', weekStatusOut: 'absents', weekStatusNoResponse: 'sans réponse',
        weekStatusShort: 'Manque de joueurs'
      });
      Object.assign(en, {
        weekStatusTitle: 'This week', weekStatusDetailBtn: 'View the game',
        weekStatusConfirmed: 'confirmed', weekStatusOut: 'out', weekStatusNoResponse: 'no reply',
        weekStatusShort: 'Short players'
      });
    }
    if (unverified) {
      Object.assign(fr, { notVerified: "Ton courriel n'est pas encore vérifié.", resendBtn: 'Renvoyer le courriel' });
      Object.assign(en, { notVerified: 'Your email is not yet verified.', resendBtn: 'Resend email' });
    }
  } else if (state === 'deactivated') {
    Object.assign(fr, {
      deactivatedOn: 'Cette ligue a été désactivée le',
      hardDeleteTitle: 'Supprimer définitivement la ligue',
      hardDeleteDesc: "Efface pour de bon toutes les données de la ligue (parties, joueurs, présences, etc.). Aucune récupération possible. Nécessite que la ligue soit déjà désactivée depuis 15 jours.",
      hardDeleteLocked: 'Débloqué le',
      hardDeleteEligible: 'La suppression définitive est débloquée.',
      hardDeleteConfirmLabel: 'Tape "SUPPRIMER" suivi du nom de ta ligue pour confirmer',
      hardDeleteConfirmPh: `SUPPRIMER ${leagueName || ''}`,
      hardDeleteBtn: 'Supprimer définitivement'
    });
    Object.assign(en, {
      deactivatedOn: 'This league was deactivated on',
      hardDeleteTitle: 'Permanently delete this league',
      hardDeleteDesc: 'Permanently erases all of this league\'s data (games, players, attendance, etc). This cannot be undone. Requires the league to have been deactivated for 15 days already.',
      hardDeleteLocked: 'Unlocks on',
      hardDeleteEligible: 'Permanent deletion is unlocked.',
      hardDeleteConfirmLabel: 'Type "DELETE" followed by your league\'s name to confirm',
      hardDeleteConfirmPh: `DELETE ${leagueName || ''}`,
      hardDeleteBtn: 'Permanently delete'
    });
  }
  return { fr, en };
}

const DASH_ICON_HOME = '<svg viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="2"><path d="M3 9l7-6 7 6v8H3z"/></svg>';
const DASH_ICON_PLAYERS = '<svg viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="2"><circle cx="10" cy="7" r="3.5"/><path d="M3 18c0-4 3-6 7-6s7 2 7 6"/></svg>';
const DASH_ICON_SCHEDULE = '<svg viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="4" width="14" height="13" rx="1"/><path d="M3 8h14M7 2v4M13 2v4"/></svg>';
const DASH_ICON_CHECK = '<svg viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="2.4"><path d="M4 10.5l4 4 8-9"/></svg>';
const DASH_ICON_SETTINGS = '<svg viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="2"><circle cx="10" cy="10" r="2.6"/><path d="M10 2.5v2.2M10 15.3v2.2M17.5 10h-2.2M4.7 10H2.5M15.1 4.9l-1.6 1.6M6.5 13.5l-1.6 1.6M15.1 15.1l-1.6-1.6M6.5 6.5L4.9 4.9"/></svg>';
// Live-testing task (batch 3), Part 2: Comms nav entry -- available to
// every league (no capability-flag gate, per the task's own explicit
// instruction), so it's a permanent 5th nav item, not conditional.
const DASH_ICON_COMMS = '<svg viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="2"><path d="M3 5.5a1.5 1.5 0 0 1 1.5-1.5h11a1.5 1.5 0 0 1 1.5 1.5v7a1.5 1.5 0 0 1-1.5 1.5H9l-4 3v-3H4.5A1.5 1.5 0 0 1 3 12.5z"/></svg>';

// Admin desktop/phone chrome (design system Part 3): nl-header with the
// real Accueil/Joueurs/Horaire nav on desktop, collapsing to a fixed
// bottom nl-tabbar on phones -- matches
// notre-ligue-design-system/components/ScreenDashboard/preview.html's
// own two layouts exactly (this same header/tabbar pair is reused by
// the roster/schedule pages below, all three sharing one active-tab
// state).
// Live-testing task, Part 1: added a 4th nav entry (settings) -- the
// per-key French fallback label lookup used to be a nested ternary
// (fine for 3 keys, unreadable for 4+), switched to a plain map.
const DASH_NAV_LABEL_FR = { navHome: 'Accueil', navRoster: 'Joueurs', navSchedule: 'Horaire', navComms: 'Comms', navSettings: 'Paramètres' };
function dashChrome(leagueName, active) {
  const nav = [
    { key: 'home', href: '/dashboard', icon: DASH_ICON_HOME, i18n: 'navHome' },
    { key: 'roster', href: '/league/roster', icon: DASH_ICON_PLAYERS, i18n: 'navRoster' },
    { key: 'schedule', href: '/league/schedule', icon: DASH_ICON_SCHEDULE, i18n: 'navSchedule' },
    { key: 'comms', href: '/league/comms', icon: DASH_ICON_COMMS, i18n: 'navComms' },
    { key: 'settings', href: '/league/settings', icon: DASH_ICON_SETTINGS, i18n: 'navSettings' }
  ];
  const header = `<header class="nl-header">
  <!-- D1 (nav polish task): a long league name ("Sunday Morning Hockey
       League") truncates against the 280px max-width with no way to
       see it in full. title= gives a native hover tooltip AND exposes
       the full name to assistive tech (the accessible name for a
       <span> with visible, truncated text) -- decided against a
       separate short-name field, which would be new config to
       maintain for a purely cosmetic nav-width problem. -->
  <span class="nl-brand" style="max-width:280px" title="${esc(leagueName)}">${esc(leagueName)}</span>
  <nav class="nl-nav">${nav.map(n => `<a href="${n.href}"${n.key === active ? ' aria-current="page"' : ''} data-i18n="${n.i18n}">${esc(DASH_NAV_LABEL_FR[n.i18n])}</a>`).join('')}</nav>
  <div class="spacer"></div>
  <div class="nl-lang" role="group" aria-label="Langue / Language">
    <button type="button" id="btn-lang-fr" aria-pressed="true" onclick="window.__setLang('fr')">FR</button>
    <button type="button" id="btn-lang-en" aria-pressed="false" onclick="window.__setLang('en')">EN</button>
  </div>
</header>`;
  const tabbar = `<nav class="nl-tabbar">${nav.map(n => `<a href="${n.href}"${n.key === active ? ' aria-current="page"' : ''}>${n.icon}<span data-i18n="${n.i18n}">${esc(DASH_NAV_LABEL_FR[n.i18n])}</span></a>`).join('')}</nav>`;
  return { header, tabbar };
}

function dashStyles() {
  return `<style>
  .nl { display: flex; flex-direction: column; min-height: 100dvh; }
  .dash-main { max-width: var(--content-wide); width: 100%; margin: 0 auto; padding: var(--space-5) var(--space-4); display: flex; flex-direction: column; gap: var(--space-5); flex: 1; }
  .dash-top { display: flex; align-items: flex-end; justify-content: space-between; gap: var(--space-4); flex-wrap: wrap; }
  .dash-top h1 { font: 700 32px/38px var(--font-display); font-stretch: 118%; letter-spacing: -.01em; }
  .dash-status { display: flex; align-items: center; gap: var(--space-2); margin-top: 6px; color: var(--ink-muted); font-size: 14px; flex-wrap: wrap; }
  .dash-week-when { display: flex; align-items: baseline; gap: var(--space-3); flex-wrap: wrap; font: 700 18px/24px var(--font-display); font-stretch: 118%; margin-top: 8px; }
  .dash-week-venue { font: 400 14px/20px var(--font-sans); color: var(--ink-muted); }
  .dash-week-counts { display: flex; gap: var(--space-2); flex-wrap: wrap; margin-top: 10px; }
  .dash-grid { display: grid; grid-template-columns: 2fr 1fr; gap: var(--space-5); }
  .dash-start { display: flex; flex-direction: column; gap: var(--space-3); padding: var(--space-5); border: 2px solid var(--primary); }
  .dash-start h2 { font: 700 26px/32px var(--font-display); font-stretch: 118%; }
  .dash-start p { color: var(--ink-muted); max-width: 520px; }
  .dash-start .acts { display: flex; gap: var(--space-3); margin-top: var(--space-2); flex-wrap: wrap; }
  .dash-check { display: flex; flex-direction: column; gap: 4px; }
  .dash-ck { display: flex; align-items: center; gap: var(--space-3); min-height: 44px; font-size: 15px; }
  .dash-ck .b { width: 24px; height: 24px; border-radius: var(--radius-sm); display: flex; align-items: center; justify-content: center; flex: none; }
  .dash-ck .b.y { background: var(--success); color: var(--on-success); }
  .dash-ck .b.n { border: 1.5px solid var(--line-strong); }
  .dash-ck .b svg { width: 16px; height: 16px; }
  .dash-ck.done span:last-child { color: var(--ink-muted); text-decoration: line-through; }
  .dash-tiles { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: var(--space-5); }
  .dash-tile .overline { margin-bottom: var(--space-2); }
  .dash-tile a { font: 600 14px/20px var(--font-sans); }
  .dash-share { display: flex; align-items: center; gap: var(--space-2); flex-wrap: wrap; }
  /* Live-testing task (batch 2), Part 9: word-break: break-all forces a
     line break at literally ANY character, ignoring natural break
     points (a slash, a hyphen) -- on a real slug this wrapped
     mid-word, unreadable. overflow-wrap: anywhere still allows a break
     wherever there's genuinely no other way to fit the text, but
     word-break: normal restores browsers' normal preference for
     breaking at an existing boundary (/, -) first, so a real URL wraps
     at a sensible spot instead of splitting a word in half. */
  .dash-share code { flex: 1; min-width: 160px; font: 500 14px/20px var(--font-sans); color: var(--primary); background: var(--primary-tint); padding: 10px 12px; border-radius: var(--radius-md); word-break: normal; overflow-wrap: anywhere; }
  .nl-error { color: var(--danger, #b3122e); font-weight: 600; font-size: 14px; }
  .nl-ok { color: var(--success, #1c7a4a); font-weight: 600; font-size: 14px; }
  .su-structure { display: flex; flex-direction: column; gap: var(--space-2); }
  .su-structure-opt { display: flex; align-items: flex-start; gap: var(--space-3); padding: var(--space-3); border: 1.5px solid var(--line-strong); border-radius: var(--radius-md); cursor: pointer; }
  .su-structure-opt.on { border: 2px solid var(--primary); background: var(--primary-tint); }
  .su-structure-opt input { margin-top: 3px; flex: none; }
  .su-structure-opt .t { font-weight: 600; font-size: 15px; display: block; }
  /* Live-testing bug fix (Part 4): see signupStyles()'s own identical
     fix -- .t/.d are inline <span>s by default, so margin-top on .d
     had no effect and the label/description ran together. */
  .su-structure-opt .d { font-size: 13px; color: var(--ink-muted); margin-top: 2px; display: block; }
  .su-two { display: grid; grid-template-columns: 1fr 1fr; gap: var(--space-3); }
  @media (min-width: 640px) { .nl-tabbar { display: none; } }
  @media (max-width: 639px) { .nl-nav { display: none; } .dash-main { padding-bottom: 76px; } .dash-grid { grid-template-columns: 1fr; } }
</style>`;
}

async function handleDashboardPage(req, env, url) {
  const lang = resolveServerLang(req);
  const session = await checkUserSession(req, env);
  if (!session) {
    return Response.redirect(url.origin + '/login', 302);
  }

  const leagueRow = await env.DB.prepare(
    `SELECT l.* FROM leagues l JOIN league_admins la ON la.league_id = l.id
      WHERE la.user_id = ? ORDER BY l.created_at DESC LIMIT 1`
  ).bind(session.userId).first();
  const verified = await isUserEmailVerified(env, session.userId);
  // Part 2: self-healing backfill -- a league created before slugs
  // existed just gets one generated and persisted the first time its
  // dashboard is loaded (see getOrCreateLeagueSlug's own comment).
  const leagueSlug = leagueRow && !leagueRow.deactivated_at ? await getOrCreateLeagueSlug(env, leagueRow) : null;

  const leagueData = leagueRow ? await getLeagueDataJson(env, leagueRow.id) : null;
  const currentSeason = leagueData ? leagueData.current_season : null;

  const teamNames = leagueRow ? (() => { try { return JSON.parse(leagueRow.team_names || '[]'); } catch (_) { return []; } })() : [];
  // Live-testing bug fix: the "Équipes" tile/card used to show
  // teamNames straight from leagues.team_names, which is real team
  // names for 'fixed'/'weekly_draw' but the internal HEADCOUNT_TEAM_NAME
  // sentinel for 'headcount' -- shown verbatim to the league's own
  // admin as if it were a real team ("1 équipe: Tous"). Branch on the
  // league's own team_structure (its permanent default -- same basis
  // teamNames itself already uses here, not a season override) instead.
  const dashTeamStructure = leagueRow ? (leagueRow.team_structure || 'fixed') : 'fixed';
  const dashIsHeadcount = dashTeamStructure === 'headcount';
  const dashIsWeeklyDraw = dashTeamStructure === 'weekly_draw';
  // B3 (onboarding polish task): "Name the teams" used to always show
  // done/struck-through on a brand-new league the moment it was
  // created -- accurate for the STEP having happened, but not for
  // "the admin actually named anything": the team-names field is
  // explicitly optional at both signup and onboarding (its own
  // placeholder/help text says so), and a league that left it
  // untouched still has "Équipe 1"/"Équipe 2" (or "Team 1"/"Team 2",
  // depending which language was active when the default got
  // generated -- checked language-agnostically here, not tied to
  // the CURRENT viewer's toggle) stored as its real team_names.
  // Complete only once the names genuinely differ from that generated
  // default. Reused below by both the pre-season checklist and the
  // post-season "next steps" card, which already had this exact
  // check -- one source of truth now instead of two.
  const defaultTeamNamePattern = /^(Équipe|Team) \d+$/;
  const stillDefaultTeamNames = !dashIsHeadcount && teamNames.length > 0 && teamNames.every(t => defaultTeamNamePattern.test(t));
  // Live-testing task, Part 5: same hasRosterLimits gate the settings
  // page uses -- see that page's own comment for why min_players/
  // max_players (never null once genuinely set) is the reliable signal,
  // not min_goalies (which defaults to 0 for every league regardless of
  // structure).
  const dashHasRosterLimits = !!(leagueRow && leagueRow.min_players != null && leagueRow.max_players != null);
  const playerCountRow = leagueRow ? await env.DB.prepare('SELECT COUNT(*) AS c FROM contacts WHERE league_id = ? AND is_active = 1').bind(leagueRow.id).first() : null;
  const playerCount = playerCountRow ? Number(playerCountRow.c) || 0 : 0;

  const publicUrl = leagueSlug ? `${url.origin}/${leagueSlug}` : `${url.origin}/league/public?league=${leagueRow ? leagueRow.id : ''}`;

  const dashState = leagueRow && leagueRow.deactivated_at ? 'deactivated' : leagueRow ? 'active' : 'none';
  const I18N_DASH = buildDashI18n({ state: dashState, needsSeason: !currentSeason, unverified: !verified, leagueName: leagueRow ? leagueRow.name : '' });

  let bodyHtml;

  if (dashState === 'none') {
    const { header } = dashChrome('Notre Ligue', 'home');
    bodyHtml = `${dashStyles()}${header}
<main class="dash-main">
  <h1 data-i18n="dashTitle">Tableau de bord</h1>
  <section class="nl-card nl-card--pad-lg">
    <p class="nl-help" data-i18n="noLeagueYet">Tu n'as pas encore de ligue.</p>
    <div style="margin-top:12px"><a class="nl-btn nl-btn--primary" id="createLeagueBtn" href="/signup?step=2" data-i18n="createLeagueCta">Créer ma ligue</a></div>
  </section>
  <button type="button" class="nl-btn nl-btn--ghost" id="logoutBtn" data-i18n="logout" onclick="doLogout()">Se déconnecter</button>
</main>`;
  } else if (dashState === 'deactivated') {
    // Live-testing task (batch 5), Part 7: co-admin invite and
    // deactivate moved to Settings, but the hard-delete section right
    // below stays here -- checkLeagueAccess (leagues.js) blocks every
    // OTHER session-gated route, including Settings, once a league is
    // deactivated (test/part56_hard_delete.spec.js's own regression
    // test locks this in: "the hard-delete UI is reachable on the
    // dashboard once a league is deactivated -- not stranded behind
    // the deactivated-league gate"). This is genuinely the one page
    // still reachable at that point, so it's the only place this
    // section can live -- not duplication, since the OTHER copy (the
    // "not yet eligible" advance notice on Settings) is only ever
    // visible while a league is still active, and this one only once
    // it's deactivated -- never both at once for the same league.
    const { header } = dashChrome(leagueRow.name, 'home');
    bodyHtml = `${dashStyles()}${header}
<main class="dash-main">
  <h1>${esc(leagueRow.name)}</h1>
  <section class="nl-card nl-card--pad-lg">
    <p class="nl-help" style="margin:0;">
      <span data-i18n="deactivatedOn">Cette ligue a été désactivée le</span> ${esc(leagueRow.deactivated_at.slice(0, 10))}.
    </p>
  </section>
  <section class="nl-card nl-card--pad-lg" style="border-color:var(--danger,#b3122e)">
    <div class="h3" data-i18n="hardDeleteTitle">Supprimer définitivement la ligue</div>
    <p class="nl-help" data-i18n="hardDeleteDesc">Efface pour de bon toutes les données de la ligue (parties, joueurs, présences, etc.). Aucune récupération possible. Nécessite que la ligue soit déjà désactivée depuis 15 jours.</p>
    <p id="hardDeleteStatus" class="nl-help"></p>
    <div id="hardDeleteErr" class="nl-error" style="display:none"></div>
    <div class="nl-field">
      <label class="nl-label" for="hard_delete_confirm" data-i18n="hardDeleteConfirmLabel">Tape "SUPPRIMER" suivi du nom de ta ligue pour confirmer</label>
      <input class="nl-input" id="hard_delete_confirm" type="text" data-i18n-ph="hardDeleteConfirmPh" placeholder="SUPPRIMER ${esc(leagueRow.name)}" autocomplete="off">
    </div>
    <div style="margin-top:8px"><button type="button" class="nl-btn nl-btn--secondary nl-btn--sm" id="hard_delete_submit" data-i18n="hardDeleteBtn" onclick="submitHardDelete()" disabled style="color:var(--danger,#b3122e);border-color:var(--danger,#b3122e);">Supprimer définitivement</button></div>
  </section>
  <button type="button" class="nl-btn nl-btn--ghost" id="logoutBtn" data-i18n="logout" onclick="doLogout()">Se déconnecter</button>
</main>`;
  } else {
    const { header, tabbar } = dashChrome(leagueRow.name, 'home');
    const needsSeason = !currentSeason;

    // Live-testing task (batch 6), Part 8: "current-week status" --
    // SMBHL's own /admin/board is this product's admin home page,
    // showing (for the next open game) per-team rosters with live
    // status, skater/goalie counts, and a shortage flag (teamState),
    // plus a substitute waitlist and drag-drop team balance. The league
    // product already has an equivalent DETAIL surface for all of that
    // (handleLeagueEventDetailPage, /league/events/detail) -- what the
    // dashboard HOME was missing is SMBHL's other habit: glancing at
    // the board on login to see how the next game is shaping up without
    // opening it. This card is that glance -- next event, confirmed/
    // out/no-response counts, and a shortage flag (eventWeekStatus,
    // shared with the future -- not a reimplementation of teamState) --
    // linking to the existing detail page for anything more. SMBHL's
    // own board is untouched; this is additive to the league product
    // only.
    // Part 2 (fixed-teams scheduling task): two events can now share a
    // date (different venue/time -- SMBHL's own real example is two
    // simultaneous gyms). This card used to pick a single "next event"
    // via LIMIT 1, which was safe only when a date was structurally
    // unique per league -- now it would silently hide a same-day
    // sibling instead of showing it. Fetches every non-cancelled event
    // on that SAME nearest date (not just the first one found) and
    // renders one row per event, each with its own real counts.
    let nextDateEvents = [];
    // Onboarding polish task (B3): "has this season's schedule been
    // started at all" -- ANY non-cancelled event, not just an upcoming
    // one (a season could be entirely in the past with a real schedule
    // behind it; that's a finished schedule, not a missing one).
    // Reused below to fold "Create the schedule" into the ONE next-
    // steps checklist instead of a separate card of its own.
    let hasAnyEvents = false;
    if (!needsSeason) {
      const anyEventRow = await env.DB.prepare(
        `SELECT id FROM events WHERE league_id = ? AND season = ? AND state != 'cancelled' LIMIT 1`
      ).bind(leagueRow.id, currentSeason).first();
      hasAnyEvents = !!anyEventRow;

      const today = new Date().toISOString().slice(0, 10);
      const nextOne = await env.DB.prepare(
        `SELECT date FROM events WHERE league_id = ? AND state != 'cancelled' AND date >= ? ORDER BY date ASC LIMIT 1`
      ).bind(leagueRow.id, today).first();
      if (nextOne) {
        const sameDate = (await env.DB.prepare(
          `SELECT id, date, venue, start_time, season FROM events
            WHERE league_id = ? AND state != 'cancelled' AND date = ?
            ORDER BY start_time ASC`
        ).bind(leagueRow.id, nextOne.date).all()).results || [];
        for (const ev of sameDate) {
          const eventCfg = await getLeagueSeasonConfig(env, leagueRow.id, ev.season);
          nextDateEvents.push({ event: ev, status: await eventWeekStatus(env, leagueRow.id, ev, eventCfg) });
        }
      }
    }
    // Onboarding polish task (B3): "Create the schedule" used to live
    // here as its own always-shown card the moment a season existed
    // but had no upcoming event -- sitting right above the SEPARATE
    // "Prochaines étapes" card below, both saying "next step," neither
    // saying how they relate. This card now only ever shows real
    // upcoming-game status; with no events at all yet, it renders
    // nothing (the unified next-steps checklist carries that
    // "create the schedule" prompt instead -- see nextStepsItems).
    const weekStatusHtml = (needsSeason || !nextDateEvents.length) ? '' : `
    <section class="nl-card nl-card--pad-lg">
      <div class="h3" data-i18n="weekStatusTitle">Cette semaine</div>
      ${nextDateEvents.map(({ event: nextEvent, status: weekStatus }) => `
      <div class="dash-week-when">${dateTimeSpanHtml('span', nextEvent.date, nextEvent.start_time, 'short')}${nextEvent.venue ? `<span class="dash-week-venue">${esc(nextEvent.venue)}</span>` : ''}</div>
      <div class="dash-week-counts">
        <span class="nl-badge nl-badge--in">${weekStatus.confirmed} <span data-i18n="weekStatusConfirmed">confirmés</span></span>
        <span class="nl-badge nl-badge--out">${weekStatus.out} <span data-i18n="weekStatusOut">absents</span></span>
        <span class="nl-badge nl-badge--pending">${weekStatus.noResponse} <span data-i18n="weekStatusNoResponse">sans réponse</span></span>
        ${weekStatus.short ? `<span class="nl-badge nl-badge--short" data-i18n="weekStatusShort">Manque de joueurs</span>` : ''}
      </div>
      <div style="margin-top:10px;margin-bottom:10px"><a class="nl-btn nl-btn--secondary nl-btn--sm" href="/league/events/detail?e=${encodeURIComponent(nextEvent.id)}" data-i18n="weekStatusDetailBtn">Voir le match</a></div>`).join('<hr style="margin:10px 0;border:none;border-top:1px solid var(--line)">')}
    </section>`;

    const remindersAnyOn = !!(leagueRow.reminder_72h_enabled || leagueRow.reminder_24h_enabled || leagueRow.reminder_12h_enabled);
    const startGridHtml = needsSeason ? `
    <div class="dash-grid">
      <section class="nl-card dash-start">
        <div class="overline" style="color:var(--primary)" data-i18n="nextStep">Prochaine étape</div>
        <h2 data-i18n="startSeason">Lance ta première saison</h2>
        <p data-i18n="startSeasonDesc">Choisis un nom pour ta saison. Tu pourras créer des matchs ensuite.</p>
        <div id="seasonErr" class="nl-error" style="display:none"></div>
        <div class="nl-field" style="max-width:360px">
          <label class="nl-label" for="season_name" data-i18n="seasonNameLabel">Nom de la saison</label>
          <input class="nl-input" id="season_name" type="text" data-i18n-ph="seasonNamePh" placeholder="Ex. Saison Hiver 2026">
        </div>
        <div class="acts"><button type="button" class="nl-btn nl-btn--primary" id="season_submit" data-i18n="seasonStartBtn" onclick="submitSeason()">Créer la saison</button></div>
      </section>
      <section class="nl-card nl-card--pad-lg">
        <div class="h3" data-i18n="checklistTitle">Pour bien partir</div>
        <div class="dash-check" style="margin-top:12px">
          <div class="dash-ck done"><span class="b y">${DASH_ICON_CHECK}</span><span data-i18n="ckLeague">Créer la ligue</span></div>
          <!-- Live-testing Bug 4: this row used to always read "Nommer
               les équipes" ("Name the teams") and always show done --
               accurate for fixed/weekly_draw (both really do pick real
               team names at signup), but a headcount league never
               names any teams at all, so it showed a false "done" for
               a step that genuinely never happened. Its own real
               signup step (picking a min/max player count) gets its
               own accurate label instead; still correctly "done" (it
               DID happen, just not team-naming) since headcount
               creation requires it up front, same as fixed/weekly_draw
               require team names up front. -->
          <!-- B3 (onboarding polish task): "Nommer les équipes" used to
               always show done the instant a league was created --
               team names are optional at signup (the field's own
               placeholder/help text says so), so "the step happened"
               didn't mean "the admin actually named anything." Done
               only once stillDefaultTeamNames says the names genuinely
               differ from the generated "Équipe 1"/"Team 1" defaults.
               headcount's own row is unaffected (see this row's
               original comment below) -- it's a different question
               (player count, not team names) that genuinely is decided
               up front. -->
          <div class="dash-ck${dashIsHeadcount || !stillDefaultTeamNames ? ' done' : ''}"><span class="b ${dashIsHeadcount || !stillDefaultTeamNames ? 'y">' + DASH_ICON_CHECK : 'n">'}</span><span data-i18n="${dashIsHeadcount ? 'ckPlayerCount' : 'ckTeams'}">${dashIsHeadcount ? 'Choisir le nombre de joueurs' : 'Nommer les équipes'}</span></div>
          <!-- Live-testing bug fix (Bug 5): season, not players, is the
               real blocking prerequisite (Bug 4 -- POST /league/events
               fails without one) for the next real step (creating
               matches), so it comes before "add players" here, matching
               the actual backend dependency order rather than an
               arbitrary one. This checklist only ever renders while
               needsSeason is true, so this row is always "not done"
               here by construction. -->
          <div class="dash-ck"><span class="b n"></span><span data-i18n="ckSeason">Créer la saison</span></div>
          <div class="dash-ck${playerCount > 0 ? ' done' : ''}"><span class="b ${playerCount > 0 ? 'y">' + DASH_ICON_CHECK : 'n">'}</span><span data-i18n="ckPlayers">Ajouter les joueurs</span></div>
          <!-- F1 (players/reminders polish task): new leagues now start
               with all three automated reminders OFF (see
               handleLeagueCreate in leagues.js) so a mid-setup player
               add never silently emails anyone. This closing checklist
               row is the promised nudge to turn them back on once the
               admin is ready -- computed live from leagueRow (settings
               are reachable pre-season too), so it flips to done the
               moment any one of the three is enabled, same pattern as
               the other rows above. -->
          <div class="dash-ck${remindersAnyOn ? ' done' : ''}"><span class="b ${remindersAnyOn ? 'y">' + DASH_ICON_CHECK : 'n">'}</span><a href="/league/settings#reminders-section" data-i18n="ckReminders">Activer les rappels automatiques</a></div>
        </div>
      </section>
    </div>` : '';

    // Live-testing task (batch 5), Part 6: once a season exists, the
    // dashboard used to show NOTHING guidance-shaped at all -- straight
    // from the "Pour bien partir" checklist to a settings-page-style
    // pile of cards. This is the ongoing version of that same idea:
    // genuinely useful next steps, computed from what's actually still
    // default/unset, not a one-time flag -- it naturally disappears
    // once everything below has a real answer, and reappears if the
    // gap comes back (e.g. every player removed again).
    // defaultTeamNamePattern/stillDefaultTeamNames computed once above
    // (B3), shared with the pre-season checklist.
    const nextStepsItems = !needsSeason ? [
      // B3: folded in from the old, separately-carded "Create the
      // schedule" prompt (weekStatusHtml's own comment) -- one
      // checklist, not two cards both claiming to be "next."
      !hasAnyEvents ? { key: 'nsCreateSchedule', href: '/league/schedule', fr: "Créer l'horaire" } : null,
      playerCount === 0 ? { key: 'nsAddPlayers', href: '/league/roster', fr: 'Ajouter des joueurs' } : null,
      stillDefaultTeamNames ? { key: 'nsNameTeams', href: '/onboarding/season?step=2', fr: 'Nommer tes équipes' } : null,
      (!dashIsHeadcount && !dashHasRosterLimits) ? { key: 'nsRosterLimits', href: '/onboarding/season?step=1', fr: "Définir l'effectif" } : null
    ].filter(Boolean) : [];
    const nextStepsHtml = nextStepsItems.length ? `
    <section class="nl-card nl-card--pad-lg" style="border-color:var(--yellow)">
      <div class="h3" data-i18n="nextStepsTitle">Prochaines étapes</div>
      <div class="dash-check" style="margin-top:12px">
        ${nextStepsItems.map(it => `<div class="dash-ck"><span class="b n"></span><a href="${it.href}" data-i18n="${it.key}">${esc(it.fr)}</a></div>`).join('')}
      </div>
    </section>` : '';

    bodyHtml = `${dashStyles()}${header}
<main class="dash-main">
  <div class="dash-top">
    <div>
      <h1>${esc(leagueRow.name)}</h1>
      ${leagueRow.division_label ? `<p class="nl-help" style="margin:2px 0 0;">${esc(leagueRow.division_label)}</p>` : ''}
      <div class="dash-status">
        ${needsSeason
          ? `<span class="nl-badge nl-badge--pending" data-i18n="noSeason">Pas de saison active</span>`
          // 4b (fixed-teams investigation follow-up batch, small
          // fixes): "Start a new season" was only reachable from
          // Settings -- added here too, always visible, as a plain
          // link beside Edit (DECIDED: a link, not a button -- the
          // rollover confirmation screen on Settings already explains
          // every consequence before anything changes, so an
          // accidental click is contained, same reasoning that keeps
          // Edit itself a plain link here rather than a button).
          : `<span><span data-i18n="currentSeasonLabel">Saison actuelle :</span> <b>${esc(currentSeason)}</b> · <a href="/league/settings" data-i18n="editSeason">Modifier</a> · <a href="/league/settings#section-new-season" data-i18n="startNewSeasonLink">Démarrer une nouvelle saison</a></span>`}
        ${needsSeason ? '' : `<span>${dashIsHeadcount ? '' : `${teamNames.length} <span data-i18n="teamsLabel">équipes</span> · `}${playerCount} <span data-i18n="playersLabel">joueurs</span></span>`}
      </div>
    </div>
  </div>
  ${!verified ? `
  <section class="nl-card nl-card--pad-lg">
    <p class="nl-help" style="margin:0;" data-i18n="notVerified">Ton courriel n'est pas encore vérifié.</p>
    <p id="resendMsg" style="margin:8px 0 0;display:none;font-size:14px;"></p>
    <div style="margin-top:10px"><button type="button" class="nl-btn nl-btn--secondary nl-btn--sm" id="resendBtn" data-i18n="resendBtn" onclick="resendVerification()">Renvoyer le courriel</button></div>
  </section>` : ''}
  ${startGridHtml}
  ${weekStatusHtml}
  ${nextStepsHtml}
  <div class="dash-tiles">
    <!-- B1 bug fix (dashboard/schedule/events polish task): before a
         season exists, these two tiles describe nothing real yet --
         "Fresh teams every game / 2" and "Players / 0" are just the
         league's own static signup-time config, not anything about an
         actual season in progress, and read as broken/empty rather than
         informative. The Getting Started checklist and next-step card
         (startGridHtml, above) already carry this screen pre-season;
         these tiles start showing once there's a real season to
         describe. Public Page tile is unaffected -- whether the public
         page is enabled and its URL are both meaningful regardless of
         season state. Wording (teamsPerGame/"Fresh teams every game")
         is UNCHANGED -- see test/part49_teams_per_game_label.spec.js's
         own do-not-revert comment; this only hides the tile earlier
         than it used to show, never touches what it says. -->
    ${needsSeason ? '' : `
    <section class="nl-card nl-card--pad-lg dash-tile">
      <div class="overline" data-i18n="${dashIsWeeklyDraw ? 'teamsPerGame' : 'teams'}">${dashIsWeeklyDraw ? 'Sans équipes fixes' : 'Équipes'}</div>
      ${dashIsHeadcount
        ? `<div class="stat tnum" style="font-size:20px" data-i18n="noFixedTeams">Aucune équipe fixe</div>`
        : `<div class="stat tnum">${teamNames.length}</div>`}
      <!-- C2 (empty-states polish task): "Pickup with teams" describes
           the league's STRUCTURE, not literally "teams" the way the
           fixed-mode tile's own "Équipes" label does -- a bare count
           under it read as unexplained (what does the 2 count?). This
           caption is scoped to weekly_draw only: fixed's own "Équipes"
           label already says exactly what the number is, no caption
           needed there. -->
      ${dashIsWeeklyDraw ? `<p class="nl-help" style="margin-top:2px" data-i18n="teamsPerGameCount">équipes disponibles</p>` : ''}
    </section>
    <section class="nl-card nl-card--pad-lg dash-tile"><div class="overline" data-i18n="navRoster">Joueurs</div><div class="stat tnum">${playerCount}</div><a href="/league/roster" data-i18n="navRoster">Joueurs</a></section>`}
    <section class="nl-card nl-card--pad-lg dash-tile">
      <div class="overline" data-i18n="publicPage">Page publique</div>
      ${leagueRow.public_page_enabled
        ? `<div class="dash-share"><code id="publicUrlLink" data-href="${esc(publicUrl)}">${esc(publicUrl)}</code><button type="button" class="nl-btn nl-btn--secondary nl-btn--sm" id="copyPublicUrlBtn" data-i18n="copyLink" onclick="copyPublicUrl()">Copier</button></div>`
        : `<p class="nl-help" style="margin-top:4px" data-i18n="publicPageDisabled">Désactivée -- personne ne peut voir cette page.</p>`}
    </section>
  </div>
  <section class="nl-card nl-card--pad-lg">
    <div class="h3" data-i18n="teams">Équipes</div>
    ${dashIsHeadcount ? `
    <p class="nl-help" style="margin-top:12px" data-i18n="noFixedTeamsDesc">Cette ligue n'a pas d'équipes fixes -- c'est une liste de joueurs unique, sans répartition en équipes.</p>` : `
    <div class="nl-list" style="margin-top:12px">
      ${teamNames.map(t => `<div class="nl-row"><span class="grow">${esc(t)}</span></div>`).join('')}
    </div>
    ${dashIsWeeklyDraw ? `<p class="nl-help" style="margin-top:12px" data-i18n="weeklyDrawTeamsDesc">Ces équipes sont assignées à chaque match, pas de façon permanente aux joueurs.</p>` : ''}`}
    </div>
    <p class="nl-help" style="margin-top:12px;"><span data-i18n="tracksResultsLabel">Résultats suivis :</span> <b data-i18n="${leagueRow.tracks_results ? 'yes' : 'no'}">${leagueRow.tracks_results ? 'Oui' : 'Non'}</b> · <span data-i18n="tracksPlayerStatsLabel">Statistiques des joueurs suivies :</span> <b data-i18n="${leagueRow.tracks_player_stats ? 'yes' : 'no'}">${leagueRow.tracks_player_stats ? 'Oui' : 'Non'}</b></p>
  </section>
  <button type="button" class="nl-btn nl-btn--ghost" id="logoutBtn" data-i18n="logout" onclick="doLogout()">Se déconnecter</button>
</main>
${tabbar}`;
  }

  const script = `
${nlAuthScript(I18N_DASH)}
async function doLogout() {
  await fetch('/auth/logout', { method: 'POST', credentials: 'same-origin' });
  window.location.href = '/login';
}
async function copyPublicUrl() {
  var link = document.getElementById('publicUrlLink');
  var btn = document.getElementById('copyPublicUrlBtn');
  var original = btn.textContent;
  var url = link.getAttribute('data-href') || link.textContent;
  var dict = window.__pageDict();
  try {
    await navigator.clipboard.writeText(url);
    btn.textContent = dict.copied;
  } catch (e) {
    var range = document.createRange();
    range.selectNode(link);
    window.getSelection().removeAllRanges();
    window.getSelection().addRange(range);
  }
  setTimeout(function() { btn.textContent = original; }, 1800);
}
async function resendVerification() {
  var btn = document.getElementById('resendBtn');
  var msg = document.getElementById('resendMsg');
  btn.disabled = true;
  try {
    var res = await fetch('/auth/resend-verification', { method: 'POST', credentials: 'same-origin', headers: window.__csrfHeader() });
    var data = await res.json().catch(function() { return {}; });
    var isFr = (window.__currentLang || 'fr') === 'fr';
    msg.textContent = (res.ok && data.ok)
      ? (isFr ? "Courriel de vérification envoyé (si ce n'est pas déjà fait)." : 'Verification email sent (if not already).')
      : (isFr ? "Échec de l'envoi. Réessaie plus tard." : 'Failed to send. Please try again later.');
  } catch (e) {
    msg.textContent = window.__errorText('NETWORK_ERROR');
  }
  msg.style.display = 'block';
  btn.disabled = false;
}
async function submitSeason() {
  var el = document.getElementById('seasonErr');
  el.style.display = 'none';
  var name = document.getElementById('season_name').value.trim();
  if (!name) { el.textContent = window.__errorText('SEASON_NAME_REQUIRED_CLIENT'); el.style.display = 'block'; return; }
  var btn = document.getElementById('season_submit');
  btn.disabled = true;
  try {
    var res = await fetch('/league/season/publish', {
      method: 'POST', credentials: 'same-origin',
      headers: Object.assign({ 'content-type': 'application/json' }, window.__csrfHeader()),
      body: JSON.stringify({ season_name: name })
    });
    var data = await res.json().catch(function() { return {}; });
    if (!res.ok || !data.ok) { el.textContent = window.__errorText(data.errorKey, data.error); el.style.display = 'block'; btn.disabled = false; return; }
    // Live-testing task (batch 5), Part 6: this used to reload the
    // dashboard right here -- landing the user straight back on a page
    // that, now that a season exists, immediately offered a "Saisons"
    // card to create ANOTHER season, with no sense of what to do next.
    // The real next steps (roster size, team names, reminders, stats)
    // now get asked in flow instead, one screen, same voice as signup.
    window.__navWithLang('/onboarding/season');
  } catch (e) {
    el.textContent = window.__errorText('NETWORK_ERROR'); el.style.display = 'block'; btn.disabled = false;
  }
}
// Live-testing task (batch 5), Part 7: submitInvite/submitDeactivate
// moved to the Settings page's own script, alongside the sections that
// use them (now removed from here). loadHardDeleteStatus/
// submitHardDelete stay -- the dashboard's 'deactivated' state still
// has its own hard-delete section, the only page reachable once a
// league is actually deactivated (Settings is not -- see this
// function's own top-of-file comment).
async function loadHardDeleteStatus() {
  var statusEl = document.getElementById('hardDeleteStatus');
  var btn = document.getElementById('hard_delete_submit');
  if (!statusEl || !btn) return;
  try {
    var res = await fetch('/league/hard-delete/status', { credentials: 'same-origin' });
    var data = await res.json().catch(function() { return {}; });
    if (!res.ok || !data.ok) { statusEl.textContent = ''; return; }
    if (data.status === 'not_deactivated') {
      statusEl.textContent = window.__pageDict().hardDeleteNotDeactivated;
      btn.disabled = true;
    } else if (data.status === 'locked') {
      statusEl.textContent = window.__pageDict().hardDeleteLocked + ' ' + new Date(data.unlockAt).toLocaleDateString();
      btn.disabled = true;
    } else if (data.status === 'eligible') {
      statusEl.textContent = window.__pageDict().hardDeleteEligible;
      btn.disabled = false;
    }
  } catch (e) {}
}
async function submitHardDelete() {
  var err = document.getElementById('hardDeleteErr');
  err.style.display = 'none';
  var confirmPhrase = document.getElementById('hard_delete_confirm').value;
  var btn = document.getElementById('hard_delete_submit');
  btn.disabled = true;
  try {
    var res = await fetch('/league/hard-delete', {
      method: 'POST', credentials: 'same-origin',
      headers: Object.assign({ 'content-type': 'application/json' }, window.__csrfHeader()),
      body: JSON.stringify({ confirmPhrase: confirmPhrase })
    });
    var data = await res.json().catch(function() { return {}; });
    if (!res.ok || !data.ok) { err.textContent = window.__errorText(data.errorKey, data.error); err.style.display = 'block'; btn.disabled = false; return; }
    window.location.href = '/login';
  } catch (e) {
    err.textContent = window.__errorText('NETWORK_ERROR'); err.style.display = 'block'; btn.disabled = false;
  }
}
if (document.getElementById('hardDeleteStatus')) loadHardDeleteStatus();
`;

  return new Response(nlDocument({ title: leagueRow ? `${lang === 'en' ? 'Dashboard' : 'Tableau de bord'} — ${leagueRow.name}` : (lang === 'en' ? 'Dashboard' : 'Tableau de bord'), description: '', bodyHtml: bodyHtml + `<script>${script}</script>`, lang }), {
    headers: { 'content-type': 'text/html; charset=utf-8', 'cache-control': 'no-store' }
  });
}

// Live-testing task (batch 5), Part 6 (BIG): onboarding used to die
// right after the first season was created -- submitSeason() just
// reloaded the dashboard, which (now that a season exists) offered a
// "Saisons" card to create ANOTHER season, with no sense of what to
// do next, while the questions that actually matter to run a league
// (roster size, team names, reminder cadences, stats tracking) sat
// buried in Settings, undiscovered unless a user went looking.
//
// This is that continuation: same visual chrome/voice as the signup
// wizard (signupStyles/signupHeader/su-* classes, not the dashboard's
// own settings-page look), a handful of short steps instead of one
// big form ("Few choices, lots of air" -- the design system's own
// principle), skippable at every step, pre-filled with whatever's
// already set so re-visiting or resuming never loses work. Every
// field here posts to the SAME existing /league/settings/*,
// /league/season/teams and /league/reminders/settings routes the
// Settings page already uses -- no new backend, no new columns, and
// everything set here stays just as editable in Settings afterward
// (this is about WHEN to ask, not where the data lives).
//
// Team-structure-aware step list: a headcount league has no team
// names to confirm, so it gets 3 steps (roster, reminders, stats)
// instead of 4 (roster, teams, reminders, stats) -- computed once,
// server-side, from the league's own already-fixed team_structure
// (chosen once at signup, never changed after). Playoff extension: a
// 'fixed' league ALSO gets a conditional 'playoffs' step (playoffs are
// meaningless for weekly_draw -- teams aren't fixed -- and headcount --
// no team concept at all -- so neither ever sees it), inserted right
// after 'teams' since the playoff questions reference the team count
// just confirmed.
function onboardingStepsFor(teamStructure) {
  if (teamStructure === 'headcount') return ['roster', 'reminders', 'stats'];
  if (teamStructure === 'weekly_draw') return ['roster', 'teams', 'reminders', 'stats'];
  return ['roster', 'teams', 'playoffs', 'reminders', 'stats'];
}

// B1 (onboarding polish task): ONE continuous step count spanning the
// whole account-creation journey, signup step 1 through onboarding's
// last screen (stats). Signup used to always claim "of 3" even though
// weekly_draw skips signup's own step 3 entirely (straight from step
// 2 to done); onboarding's own 3-4 screens had a progress bar but no
// step NUMBER at all. The done screen deliberately stays uncounted --
// it never had a stepper (a one-off confirmation, not a form step).
// Total varies by team structure, only known once it's actually
// chosen on step 2:
//   fixed:       signup 1,2,3 + onboarding roster,teams,playoffs,reminders,stats = 8
//   headcount:   signup 1,2,3 + onboarding roster,reminders,stats                = 6
//   weekly_draw: signup 1,2   + onboarding roster,teams,reminders,stats          = 6
// Steps 1/2 render before a structure is chosen -- they show the
// pre-selected 'fixed' structure's total (8) as the honest current
// best guess (never an impossible/unreachable number); the real total
// takes over the moment a structure is actually chosen (client-side
// on step 3 for fixed/headcount -- see su_step3_title's own swap
// logic -- or server-side straight from step 2 for weekly_draw, which
// knows its structure by the time onboarding starts). Playoff
// extension: added fixed's own conditional 'playoffs' step (between
// 'teams' and 'reminders') -- fixed's total goes from 7 to 8;
// headcount/weekly_draw are completely untouched (neither structure
// ever sees a playoffs step, so neither total number changes).
const FLOW_TOTAL_STEPS = { fixed: 8, headcount: 6, weekly_draw: 6 };
const FLOW_STEP_NUMBER = {
  fixed: { signup3: 3, roster: 4, teams: 5, playoffs: 6, reminders: 7, stats: 8 },
  headcount: { signup3: 3, roster: 4, reminders: 5, stats: 6 },
  weekly_draw: { roster: 3, teams: 4, reminders: 5, stats: 6 }
};
function flowStepLabel(lang, current, total) {
  return lang === 'en' ? `Step ${current} of ${total}` : `Étape ${current} sur ${total}`;
}

function flowStepper(current, total) {
  const dots = Array.from({ length: total }, (_, i) => i + 1)
    .map(i => `<i class="${i < current ? 'done' : i === current ? 'on' : ''}"></i>`).join('');
  return `<div class="nl-steps" role="progressbar" aria-valuemin="1" aria-valuemax="${total}" aria-valuenow="${current}">${dots}</div>`;
}

