var BULK_HEADER_WORDS = ['name', 'nom', 'full name', 'nom complet', 'email', 'e-mail', 'courriel', 'phone', 'téléphone', 'telephone', 'tel'];
function parseBulkText(text) {
  // Live-testing bug fix (Part 1, URGENT regression, root cause of the
  // roster page's "Ajouter" button doing nothing). This whole function
  // is written as literal text inside index.js's own outer server-side
  // template literal (the big "const script = ..." string built by
  // handleLeagueRosterPage), so every backslash escape below goes
  // through TWO rounds of JS parsing: once when THIS FILE loads in the
  // Workers runtime, once more when the resulting text is later parsed
  // as real JS in the browser. A backslash written only once here only
  // survives ONE of those rounds -- the outer (server-side) parse
  // silently drops a lone backslash before any character that isn't a
  // recognized string escape (a digit-class shorthand became a bare
  // letter), and turns a lone carriage-return-then-newline escape pair
  // into REAL raw control-character bytes. A raw newline character
  // landing inside a slash-delimited regex literal is flat-out illegal
  // JS syntax -- which silently killed this entire inline script block
  // (a syntax error anywhere in a script tag prevents every function in
  // it from being defined at all, including submitContact). Confirmed
  // by reproducing the exact syntax error with new Function on the
  // rendered output locally before writing this fix. Writing every
  // backslash TWICE below is what makes a single backslash survive the
  // first (server-side) round intact, arriving correctly in the browser
  // for the second round where it needs to mean something to a regex.
  var isEmailField = function(f) { return f.indexOf('@') !== -1; };
  var isPhoneField = function(f) { return /^[\\d+().\\s-]{7,}$/.test(f); };
  var lines = text.split(/\\r\\n|\\r|\\n/);
  var rows = [];
  var headerChecked = false;
  for (var i = 0; i < lines.length; i++) {
    var raw = lines[i];
    if (!raw || !raw.trim()) continue;
    var sep = raw.indexOf('\\t') !== -1 ? '\\t' : ',';
    var fields = raw.split(sep).map(function(f) { return f.trim(); });
    while (fields.length && !fields[fields.length - 1]) fields.pop();
    if (!fields.length) continue;
    if (!headerChecked) {
      headerChecked = true;
      var looksHeader = fields.some(function(f) { return BULK_HEADER_WORDS.indexOf(f.toLowerCase()) !== -1; });
      if (looksHeader) continue;
    }
    // Live-testing task (batch 2), Part 2: a paste can arrive as one
    // single physical line holding SEVERAL people (missing line breaks
    // between records, e.g. a comma-separated dump with no newlines at
    // all) -- the old code always treated one physical line as exactly
    // one record, so every field on that line silently got jammed into
    // one row (all names concatenated, only the LAST email/phone found
    // kept). Two or more email addresses (or two or more phone-looking
    // fields) on the same physical line is an unambiguous signal that
    // multiple records got flattened onto it, so that case is chunked
    // into separate records instead of parsed as a single one. The
    // record-boundary signal is exactly what real pastes look like:
    // once the CURRENT record already has an email or a phone, the next
    // plain (non-email, non-phone) field is name-like text belonging to
    // a NEW record, not more of this one's name -- an email or phone
    // immediately followed by more such text is what starts the next
    // record.
    var emailCount = 0, phoneCount = 0;
    for (var c = 0; c < fields.length; c++) {
      if (isEmailField(fields[c])) emailCount++;
      else if (isPhoneField(fields[c])) phoneCount++;
    }
    if (emailCount >= 2 || phoneCount >= 2) {
      var cur = null;
      var flushChunk = function() {
        if (cur && (cur.nameParts.length || cur.email || cur.phone)) {
          rows.push({
            name: cur.nameParts.join(' ').replace(/\\s+/g, ' ').trim(),
            email: cur.email,
            phone: cur.phone
          });
        }
        cur = { nameParts: [], email: '', phone: '' };
      };
      flushChunk();
      for (var f = 0; f < fields.length; f++) {
        var field = fields[f];
        if (isEmailField(field)) {
          if (cur.email) flushChunk();
          cur.email = field;
        } else if (isPhoneField(field)) {
          if (cur.phone) flushChunk();
          cur.phone = field;
        } else {
          if (cur.email || cur.phone) flushChunk();
          cur.nameParts.push(field);
        }
      }
      flushChunk();
      continue;
    }
    var remaining = fields.slice();
    var emailIdx = -1;
    for (var j = 0; j < remaining.length; j++) { if (isEmailField(remaining[j])) { emailIdx = j; break; } }
    var email = emailIdx !== -1 ? remaining.splice(emailIdx, 1)[0] : '';
    var phoneIdx = -1;
    for (var k = 0; k < remaining.length; k++) { if (isPhoneField(remaining[k])) { phoneIdx = k; break; } }
    var phone = phoneIdx !== -1 ? remaining.splice(phoneIdx, 1)[0] : '';
    var name = remaining.join(' ').replace(/\\s+/g, ' ').trim();
    rows.push({ name: name, email: email, phone: phone });
  }
  return rows;
}
var BULK_ROWS = [];
function bulkTableCell(text, cls) {
  var td = document.createElement('td');
  if (cls) td.className = cls;
  td.textContent = text;
  return td;
}
function bulkPreview() {
  var errEl = document.getElementById('bulkErr'); errEl.style.display = 'none';
  var dict = window.__pageDict();
  var rows = parseBulkText(document.getElementById('ro_bulk_text').value);
  if (!rows.length) { errEl.textContent = dict.bulkEmptyErr; errEl.style.display = 'block'; return; }
  var seen = {};
  var okCount = 0;
  BULK_ROWS = [];
  var tbody = document.getElementById('ro_bulk_tbody');
  tbody.innerHTML = '';
  rows.forEach(function(r) {
    var status = 'ok';
    if (!r.name || r.name.split(' ').filter(Boolean).length < 2) { status = 'noname'; }
    else if (r.email && seen[r.email.toLowerCase()]) { status = 'dupe'; }
    if (status === 'ok') { okCount++; if (r.email) seen[r.email.toLowerCase()] = true; BULK_ROWS.push(r); }
    var statusText = status === 'ok' ? dict.bulkStatusOk : status === 'noname' ? dict.bulkStatusNoName : dict.bulkStatusDupeBatch;
    var tr = document.createElement('tr');
    tr.appendChild(bulkTableCell(r.name || '—'));
    tr.appendChild(bulkTableCell(r.email || '—'));
    tr.appendChild(bulkTableCell(r.phone || '—'));
    tr.appendChild(bulkTableCell(statusText, status !== 'ok' ? 'ro-bulk-skip' : ''));
    tbody.appendChild(tr);
  });
  document.getElementById('ro_bulk_summary').textContent = dict.bulkSummary.split('{ok}').join(String(okCount)).split('{total}').join(String(rows.length));
  document.getElementById('ro_bulk_preview').style.display = 'flex';
  document.getElementById('ro_bulk_confirm').disabled = okCount === 0;
}
async function bulkConfirm() {
  if (!BULK_ROWS.length) return;
  var btn = document.getElementById('ro_bulk_confirm');
  btn.disabled = true;
  var errEl = document.getElementById('bulkErr'); errEl.style.display = 'none';
  try {
    var res = await fetch('/league/contacts/bulk', {
      method: 'POST', credentials: 'same-origin',
      headers: Object.assign({ 'content-type': 'application/json' }, window.__csrfHeader()),
      body: JSON.stringify({ contacts: BULK_ROWS.map(function(r) { return { name: r.name, email: r.email || undefined, phone: r.phone || undefined }; }) })
    });
    var data = await res.json().catch(function() { return {}; });
    if (!res.ok || !data.ok) { errEl.textContent = window.__errorText(data.errorKey, data.error); errEl.style.display = 'block'; btn.disabled = false; return; }
    window.location.reload();
  } catch (e) {
    errEl.textContent = window.__errorText('NETWORK_ERROR'); errEl.style.display = 'block'; btn.disabled = false;
  }
}
